@Test
void promptContributorsReachProviderInDeterministicBudgetedSystemPrompt() {
    var provider = new ScriptedModelProvider().enqueue(List.of(
            new ScriptedModelProvider.Step.Complete(Usage.ZERO, ModelStreamEvent.StopReason.STOP)));
    PromptContributor contributor = new PromptContributor() {
        @Override public ContributorId id() { return new ContributorId("project-context"); }
        @Override public ResourceDescriptor.SourceId source() { return new ResourceDescriptor.SourceId("fixture"); }
        @Override public int priority() { return 10; }
        @Override public int tokenBudget() { return 100; }
        @Override public Contribution contribute(PromptContext context) {
            return new Contribution("Use the repository conventions.");
        }
    };
    try (var runtime = new AgentRuntimeBuilder().provider(provider).sessionStore(new MemorySessionStore())
            .promptContributor(contributor).promptTokenCounter(String::length).promptTokenBudget(100)
            .idGenerator(new SequentialIds()).build()) {
        runtime.newSession(new SessionOptions(new ModelRef("faux", "faux-1"), "."))
                .prompt("hello").completion().toCompletableFuture().join();
        String system = provider.capturedRequests().getFirst().systemPrompt();
        assertTrue(system.contains("Use the repository conventions."));
        assertTrue(system.contains("working in ."));
    }
}

@Test
void builtInPromptsHaveSymmetricEnglishAndChineseContracts() {
    var templates = BuiltinPromptTemplates.templates();
    assertEquals(4, templates.size());
    assertEquals(templates.stream().filter(value -> value.locale().equals("en")).map(value -> value.id()).sorted().toList(),
            templates.stream().filter(value -> value.locale().equals("zh-CN")).map(value -> value.id()).sorted().toList());
    assertEquals(templates.stream().filter(value -> value.locale().equals("en")).map(value -> value.variableContract()).toList(),
            templates.stream().filter(value -> value.locale().equals("zh-CN")).map(value -> value.variableContract()).toList());
}

